    ? 'Addressee: the decision-maker, first name ' + firstName + (it.person_title ? ', title ' + it.person_title : '') + '. You may use the first name once.'
    : 'Addressee: the business team. Do NOT name any individual person.',
  'Evidence (the only specific fact you may use): "' + it.evidence_quote + '"'
].join('\n');
const langRule = it.language === 'my'
  ? 'Write middle_text in Myanmar (Burmese) Unicode script only. Use the first-person form ' + it.first_person_form + '. Plain respectful business register.'
  : 'Write middle_text in English. Plain respectful business register.';
let user = facts + '\n\n' + langRule;
if (it.attempt === 2 && it.reason_codes) {
  user += '\n\nYour previous draft was rejected for these reasons: ' + it.reason_codes + '. Fix exactly those problems.';
}
const system = 'You write the MIDDLE section of one short first outreach message. Return ONLY a JSON object: {"subject": string|null, "middle_text": string, "evidence_quote_used": string}. Rules: base one sentence on the evidence and copy the evidence text exactly into evidence_quote_used; invent NOTHING (no numbers, prices, dates, names, links, results, or promises that are not in the facts); no hype, no urgency, no guarantees; ' +
  (it.channel === 'email' ? 'subject: a short honest subject line (never starting with Re: or Fw:).' : 'subject: must be null (this is a Messenger message).');
outs.push({ json: { ...it, payload: { model: 'muse-spark-1.3', temperature: 0.4,
