const rows = $input.all().map(i => i.json);
const batch = rows.filter(r => r.kind === 'batch');
const pool = rows.filter(r => r.kind === 'pool');
function grams(text, strip) {
  let t = (text || '').toLowerCase();
  for (const s of strip) if (s) t = t.split(String(s).toLowerCase()).join(' ');
  t = t.replace(/[^a-z0-9\u1000-\u109F]+/g, ' ').replace(/\s+/g, ' ').trim();
  const set = new Set();
  const words = t.split(' ').filter(w => w.length > 1);
  for (const w of words) set.add('w:' + w);
  const flat = t.replace(/ /g, '');
  for (let i = 0; i + 4 <= flat.length; i++) set.add('g:' + flat.slice(i, i + 4));
  return set;
}
function jac(a, b) {
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  const uni = a.size + b.size - inter;
  return uni ? inter / uni : 0;
}
const poolSets = pool.map(r => ({ id: r.draft_id, g: grams(r.body, [r.company_name, r.person_name, r.evidence_quote]) }));
const batchSets = batch.map(r => ({ id: r.draft_id, company_id: r.company_id, body: r.body, g: grams(r.body, [r.company_name, r.person_name, r.evidence_quote]) }));
const rejects = [];
const seen = [];
for (const b of batchSets) {
  let bad = false;
  for (const p of poolSets) { if (jac(b.g, p.g) > 0.85) { bad = true; break; } }
  if (!bad) for (const s of seen) { if (jac(b.g, s.g) > 0.85) { bad = true; break; } }
  if (bad) rejects.push({ draft_id: b.id, body: b.body });
  else seen.push(b);
}
return [{ json: { rejects_json: JSON.stringify(rejects), rejected: rejects.length, batch_size: batch.length } }];
